+    private static final int SIGN_32_BIT = 1 << 31;
+
+    /**
+     * This is a bitwise transformation to prepare 32-bit IEEE 754
+     * floating-point numbers for Radix sort: shifts and flips all
+     * bits if the value is negative, and then applies the mask.
+     *
+     * @param f the given float value
+     * @return prepared bits
+     */
+    @ForceInline
+    private static int f2i(float f, int shift, int mask) {
+        int x = Float.floatToRawIntBits(f);
+        return ((x >> 31) ^ (x >> shift)) & mask;
+    }
+
+    /**
+     * This is a bitwise transformation to prepare 32-bit IEEE 754
+     * floating-point numbers for Radix sort: shifts and flips the
+     * bits if the value is negative, otherwise flips the sign bit
